// Auto-generated gzip-compressed inline GLB module from gym_interior_v5.glb (2893620 raw -> 1062610 gz bytes)
export const GLB_META = { rawBytes: 2893620, gzBytes: 1062610, compressed: true };
const GLB_GZ_BASE64 = "";

export async function decodeGymInteriorV5Glb() {
  const bin = atob(GLB_GZ_BASE64);
  const len = bin.length;
  const gzArr = new Uint8Array(len);
  for (let i = 0; i < len; i++) gzArr[i] = bin.charCodeAt(i);
  if (typeof DecompressionStream === 'function') {
    const stream = new Blob([gzArr]).stream().pipeThrough(new DecompressionStream('gzip'));
    return await new Response(stream).arrayBuffer();
  }
  throw new Error('DecompressionStream("gzip") unavailable in this runtime.');
}
